  Mc('Has he ever ___ a stone like this?', 'found', 'find', 'finding', 'Has he ever + V3: found.', V('stone')),
  Mc('I ___ never slept in a tent.', 'have', 'has', 'am', 'I → have never slept.', V('tent')),
  Mc('___ you ever climbed a hill?', 'Have', 'Has', 'Are', 'You → Have you ever…?', V('hill')),
  Fl('I have ___ a cave. (explore)', 'explored', ['explored', 'explore', 'exploring'], 'have + V3: explored.', V('cave')),
  Fl('She has ___ in a tent. (sleep)', 'slept', ['slept', 'sleep', 'sleeping'], 'has + V3: slept.', V('tent')),
  Fl('Have you ever ___ a bear? (see)', 'seen', ['seen', 'saw', 'see'], 'Have you ever + V3: seen.'),
  Fl('He has never ___ to a cave. (be)', 'been', ['been', 'was', 'be'], 'has never + V3: been.', V('cave')),
  Fl('We ___ never climbed this hill.', 'have', ['have', 'has', 'are'], 'We → have never climbed.', V('hill')),
  Fl('___ you ever slept in a tent?', 'Have', ['Have', 'Has', 'Are'], 'You → Have you ever…?', V('tent')),
  Fl('She ___ never seen the stars.', 'has', ['has', 'have', 'is'], 'She → has never seen.', V('stars')),
  Fl('Has he ever ___ a stone? (find)', 'found', ['found', 'find', 'finding'], 'Has he ever + V3: found.', V('stone')),
